use xiom.io;

use xiom.string;
enum FileType {
  Image(ext: Str),
  Document(ext: Str),
  Video(ext: Str),
  Unknown,
}

fn ends_with(filename: Str, ext: Str) -> Bool {
  let name_len = string.str_len(filename);
  let ext_len = string.str_len(ext);
  if name_len < ext_len { return false; }
  return true;
}

fn detect(filename: Str) -> FileType {
  if ends_with(filename, "jpg") || ends_with(filename, "png") || ends_with(filename, "gif") {
    return FileType.Image("jpg");
  }
  if ends_with(filename, "pdf") || ends_with(filename, "txt") || ends_with(filename, "doc") {
    return FileType.Document("pdf");
  }
  if ends_with(filename, "mp4") || ends_with(filename, "avi") || ends_with(filename, "mov") {
    return FileType.Video("mp4");
  }
  return FileType.Unknown;
}

fn is_media(ft: FileType) -> Bool {
  match ft {
    Image(_) => { return true; }
    Video(_) => { return true; }
    _ => { return false; }
  }
}

fn main() -> Int {
  let f1 = detect("photo.jpg");
  let f2 = detect("report.pdf");
  let f3 = detect("movie.mp4");
  let f4 = detect("program.exe");
  var count = 0;
  if is_media(f1) { count = count + 1; }
  if is_media(f2) { count = count + 1; }
  if is_media(f3) { count = count + 1; }
  if is_media(f4) { count = count + 1; }
  return count;
}
